def _id_list(value):
    if value is None:
        return None
    if isinstance(value, str):
        import json
        try:
            value = json.loads(value or '[]')
        except ValueError:
            return None
    if not isinstance(value, (list, tuple)):
        return None
    return [str(item).strip() for item in value if str(item).strip()]

